CREATE DATABASE IF NOT EXISTS `detective_query`;
USE `detective_query`;
SET FOREIGN_KEY_CHECKS = 0;

DROP TABLE IF EXISTS `account_change_requests`;
CREATE TABLE `account_change_requests` (
  `request_id` int NOT NULL AUTO_INCREMENT,
  `user_id` int NOT NULL,
  `request_type` varchar(50) NOT NULL,
  `old_value` varchar(255) DEFAULT NULL,
  `new_value` varchar(255) NOT NULL,
  `reason` text DEFAULT NULL,
  `status` enum('pending','approved','rejected') DEFAULT 'pending',
  `reject_reason` text DEFAULT NULL,
  `created_at` timestamp DEFAULT CURRENT_TIMESTAMP,
  `reviewed_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`request_id`) ,
  KEY `fk_1` (`user_id`),
  FOREIGN KEY (`user_id`) REFERENCES `users` (`user_id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin AUTO_INCREMENT=150001;

DROP TABLE IF EXISTS `achievements`;
CREATE TABLE `achievements` (
  `achievement_id` int NOT NULL AUTO_INCREMENT,
  `title` varchar(150) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `description` text COLLATE utf8mb4_general_ci DEFAULT NULL,
  `points_required` int DEFAULT NULL,
  PRIMARY KEY (`achievement_id`) 
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci AUTO_INCREMENT=30006;

DROP TABLE IF EXISTS `attempts`;
CREATE TABLE `attempts` (
  `attempt_id` int NOT NULL AUTO_INCREMENT,
  `user_id` int DEFAULT NULL,
  `case_id` int DEFAULT NULL,
  `sql_query` text COLLATE utf8mb4_general_ci DEFAULT NULL,
  `final_answer` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `is_correct` tinyint DEFAULT NULL,
  `score_awarded` int DEFAULT NULL,
  `time_taken` int DEFAULT NULL,
  `execution_time_ms` float DEFAULT NULL,
  `attempt_number` int DEFAULT NULL,
  `attempt_date` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `room_id` int DEFAULT NULL,
  `session_id` int DEFAULT NULL,
  `mode` enum('Practice','Rank') COLLATE utf8mb4_general_ci DEFAULT 'Practice',
  PRIMARY KEY (`attempt_id`) ,
  KEY `user_id` (`user_id`),
  KEY `case_id` (`case_id`),
  KEY `idx_attempts_rank` (`room_id`,`user_id`,`mode`),
  KEY `idx_attempts_case` (`case_id`),
  FOREIGN KEY (`user_id`) REFERENCES `users` (`user_id`) ON DELETE CASCADE,
  FOREIGN KEY (`case_id`) REFERENCES `cases` (`case_id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci AUTO_INCREMENT=1230159;

DROP TABLE IF EXISTS `case_notes`;
CREATE TABLE `case_notes` (
  `note_id` int NOT NULL AUTO_INCREMENT,
  `user_id` int DEFAULT NULL,
  `case_id` int DEFAULT NULL,
  `note_text` text COLLATE utf8mb4_general_ci DEFAULT NULL,
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`note_id`) 
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

DROP TABLE IF EXISTS `case_objectives`;
CREATE TABLE `case_objectives` (
  `objective_id` int NOT NULL AUTO_INCREMENT,
  `case_id` int DEFAULT NULL,
  `objective_order` int DEFAULT NULL,
  `objective_text` varchar(500) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `expected_query` text COLLATE utf8mb4_general_ci DEFAULT NULL,
  `validation_type` enum('result','pattern') COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'result',
  `required_keyword` varchar(100) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `points` int DEFAULT '10',
  PRIMARY KEY (`objective_id`) ,
  KEY `fk_case_objectives_case` (`case_id`),
  FOREIGN KEY (`case_id`) REFERENCES `cases` (`case_id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci AUTO_INCREMENT=90025;

DROP TABLE IF EXISTS `case_study_materials`;
CREATE TABLE `case_study_materials` (
  `case_id` int NOT NULL,
  `file_name` varchar(255) NOT NULL,
  `mime_type` varchar(100) DEFAULT 'application/pdf',
  `file_size` int DEFAULT '0',
  `file_data` longblob NOT NULL,
  `uploaded_by` int DEFAULT NULL,
  `created_at` timestamp DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`case_id`) ,
  FOREIGN KEY (`case_id`) REFERENCES `cases` (`case_id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;

DROP TABLE IF EXISTS `cases`;
CREATE TABLE `cases` (
  `case_id` int NOT NULL AUTO_INCREMENT,
  `title` varchar(200) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `description` text COLLATE utf8mb4_general_ci DEFAULT NULL,
  `objectives` text COLLATE utf8mb4_general_ci DEFAULT NULL,
  `dataset_id` int DEFAULT NULL,
  `difficulty_id` int DEFAULT NULL,
  `correct_query` text COLLATE utf8mb4_general_ci DEFAULT NULL,
  `base_points` int DEFAULT '100',
  `is_active` tinyint DEFAULT '1',
  `unlock_xp_required` int DEFAULT '0',
  `correct_suspect_id` int DEFAULT NULL,
  `mode` enum('Practice','Rank') COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'Practice',
  `sql_type` enum('DQL','DML','DDL') COLLATE utf8mb4_general_ci DEFAULT 'DQL',
  `setup_sql` text COLLATE utf8mb4_general_ci DEFAULT NULL,
  `expected_result_sql` text COLLATE utf8mb4_general_ci DEFAULT NULL,
  PRIMARY KEY (`case_id`) ,
  KEY `dataset_id` (`dataset_id`),
  KEY `difficulty_id` (`difficulty_id`),
  FOREIGN KEY (`dataset_id`) REFERENCES `datasets` (`dataset_id`),
  FOREIGN KEY (`difficulty_id`) REFERENCES `difficulty` (`difficulty_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci AUTO_INCREMENT=60029;

DROP TABLE IF EXISTS `datasets`;
CREATE TABLE `datasets` (
  `dataset_id` int NOT NULL AUTO_INCREMENT,
  `dataset_name` varchar(150) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `schema_definition` text COLLATE utf8mb4_general_ci DEFAULT NULL,
  `sample_data` text COLLATE utf8mb4_general_ci DEFAULT NULL,
  PRIMARY KEY (`dataset_id`) 
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci AUTO_INCREMENT=30004;

DROP TABLE IF EXISTS `difficulty`;
CREATE TABLE `difficulty` (
  `difficulty_id` int NOT NULL AUTO_INCREMENT,
  `difficulty_name` varchar(50) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `multiplier` decimal(5,2) DEFAULT '1.00',
  PRIMARY KEY (`difficulty_id`) 
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci AUTO_INCREMENT=30006;

DROP TABLE IF EXISTS `game_sessions`;
CREATE TABLE `game_sessions` (
  `session_id` int NOT NULL AUTO_INCREMENT,
  `room_id` int DEFAULT NULL,
  `case_id` int DEFAULT NULL,
  `difficulty_id` int DEFAULT NULL,
  `start_time` datetime DEFAULT NULL,
  `end_time` datetime DEFAULT NULL,
  `is_active` tinyint DEFAULT '1',
  `personal_time_limit` int DEFAULT '10',
  `status` enum('Scheduled','Active','Ended') COLLATE utf8mb4_general_ci DEFAULT 'Scheduled',
  `is_paused` tinyint(1) NOT NULL DEFAULT '0',
  `paused_at` datetime DEFAULT NULL,
  `paused_seconds` int NOT NULL DEFAULT '0',
  PRIMARY KEY (`session_id`) ,
  KEY `case_id` (`case_id`),
  KEY `difficulty_id` (`difficulty_id`),
  KEY `idx_game_sessions_active` (`room_id`,`is_active`),
  FOREIGN KEY (`room_id`) REFERENCES `rooms` (`room_id`) ON DELETE CASCADE,
  FOREIGN KEY (`case_id`) REFERENCES `cases` (`case_id`),
  FOREIGN KEY (`difficulty_id`) REFERENCES `difficulty` (`difficulty_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci AUTO_INCREMENT=1020097;

DROP TABLE IF EXISTS `notifications`;
CREATE TABLE `notifications` (
  `notification_id` int NOT NULL AUTO_INCREMENT,
  `user_id` int DEFAULT NULL,
  `sender_id` int NOT NULL,
  `message` text COLLATE utf8mb4_general_ci DEFAULT NULL,
  `is_read` tinyint DEFAULT '0',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `notification_type` varchar(50) COLLATE utf8mb4_general_ci DEFAULT 'announcement',
  PRIMARY KEY (`notification_id`) ,
  KEY `user_id` (`user_id`),
  FOREIGN KEY (`user_id`) REFERENCES `users` (`user_id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci AUTO_INCREMENT=330073;

DROP TABLE IF EXISTS `refresh_tokens`;
CREATE TABLE `refresh_tokens` (
  `id` int NOT NULL AUTO_INCREMENT,
  `user_id` int NOT NULL,
  `token` varchar(512) COLLATE utf8mb4_general_ci NOT NULL,
  `expires_at` datetime NOT NULL,
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) ,
  KEY `idx_token` (`token`(255)),
  KEY `idx_user_id` (`user_id`),
  FOREIGN KEY (`user_id`) REFERENCES `users` (`user_id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci AUTO_INCREMENT=2790095;

DROP TABLE IF EXISTS `registration_requests`;
CREATE TABLE `registration_requests` (
  `request_id` int NOT NULL AUTO_INCREMENT,
  `first_name` varchar(100) COLLATE utf8mb4_general_ci NOT NULL,
  `last_name` varchar(100) COLLATE utf8mb4_general_ci NOT NULL,
  `full_name` varchar(200) COLLATE utf8mb4_general_ci GENERATED ALWAYS AS (concat(`first_name`, _utf8mb4' ', `last_name`)) STORED,
  `email` varchar(150) COLLATE utf8mb4_general_ci NOT NULL,
  `password_hash` text COLLATE utf8mb4_general_ci NOT NULL,
  `role_id` int NOT NULL DEFAULT '1',
  `sex` varchar(10) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `section` varchar(20) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `student_id` varchar(50) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `teacher_id` varchar(50) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `status` enum('pending','approved','rejected') COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'pending',
  `reject_reason` text COLLATE utf8mb4_general_ci DEFAULT NULL,
  `requested_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `reviewed_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`request_id`) ,
  UNIQUE KEY `email` (`email`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci AUTO_INCREMENT=240002;

DROP TABLE IF EXISTS `roles`;
CREATE TABLE `roles` (
  `role_id` int NOT NULL AUTO_INCREMENT,
  `role_name` varchar(50) COLLATE utf8mb4_general_ci DEFAULT NULL,
  PRIMARY KEY (`role_id`) ,
  UNIQUE KEY `role_name` (`role_name`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci AUTO_INCREMENT=30004;

DROP TABLE IF EXISTS `room_students`;
CREATE TABLE `room_students` (
  `room_students_id` int NOT NULL AUTO_INCREMENT,
  `room_id` int DEFAULT NULL,
  `student_id` int DEFAULT NULL,
  `status` enum('Pending','Approved','Rejected') COLLATE utf8mb4_general_ci DEFAULT 'Pending',
  `requested_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`room_students_id`) ,
  KEY `student_id` (`student_id`),
  KEY `idx_room_students` (`room_id`,`student_id`),
  FOREIGN KEY (`room_id`) REFERENCES `rooms` (`room_id`) ON DELETE CASCADE,
  FOREIGN KEY (`student_id`) REFERENCES `users` (`user_id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci AUTO_INCREMENT=210018;

DROP TABLE IF EXISTS `rooms`;
CREATE TABLE `rooms` (
  `room_id` int NOT NULL AUTO_INCREMENT,
  `teacher_id` int NOT NULL,
  `room_name` varchar(100) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `room_code` varchar(10) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `is_archived` tinyint(1) NOT NULL DEFAULT '0',
  `archived_at` datetime DEFAULT NULL,
  PRIMARY KEY (`room_id`) ,
  UNIQUE KEY `room_code` (`room_code`),
  KEY `teacher_id` (`teacher_id`),
  FOREIGN KEY (`teacher_id`) REFERENCES `users` (`user_id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci AUTO_INCREMENT=150008;

DROP TABLE IF EXISTS `session_objectives`;
CREATE TABLE `session_objectives` (
  `id` int NOT NULL AUTO_INCREMENT,
  `session_id` int DEFAULT NULL,
  `user_id` int DEFAULT NULL,
  `objective_id` int DEFAULT NULL,
  `objective_text` varchar(500) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `points_awarded` int DEFAULT '0',
  `is_completed` tinyint DEFAULT '0',
  `completed_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`) ,
  UNIQUE KEY `unique_session_objective` (`session_id`,`user_id`,`objective_id`),
  UNIQUE KEY `unique_completion` (`session_id`,`user_id`,`objective_id`),
  KEY `session_id_idx` (`session_id`,`user_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci AUTO_INCREMENT=360032;

DROP TABLE IF EXISTS `user_achievements`;
CREATE TABLE `user_achievements` (
  `user_achievement_id` int NOT NULL AUTO_INCREMENT,
  `user_id` int DEFAULT NULL,
  `achievement_id` int DEFAULT NULL,
  `date_earned` datetime DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`user_achievement_id`) ,
  KEY `user_id` (`user_id`),
  KEY `achievement_id` (`achievement_id`),
  FOREIGN KEY (`user_id`) REFERENCES `users` (`user_id`) ON DELETE CASCADE,
  FOREIGN KEY (`achievement_id`) REFERENCES `achievements` (`achievement_id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci AUTO_INCREMENT=30017;

DROP TABLE IF EXISTS `user_avatars`;
CREATE TABLE `user_avatars` (
  `user_id` int NOT NULL,
  `file_name` varchar(255) NOT NULL,
  `mime_type` varchar(100) DEFAULT 'image/png',
  `file_size` int DEFAULT '0',
  `file_data` longblob NOT NULL,
  `created_at` timestamp DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`user_id`) ,
  FOREIGN KEY (`user_id`) REFERENCES `users` (`user_id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;

DROP TABLE IF EXISTS `user_case_progress`;
CREATE TABLE `user_case_progress` (
  `progress_id` int NOT NULL AUTO_INCREMENT,
  `user_id` int NOT NULL,
  `case_id` int NOT NULL,
  `status` enum('Locked','Unlocked','Completed') COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'Locked',
  `highest_score` int DEFAULT NULL,
  `is_unlocked` tinyint(1) NOT NULL DEFAULT '0',
  `completed_at` datetime DEFAULT NULL,
  `investigation_score` int DEFAULT '0',
  PRIMARY KEY (`progress_id`) ,
  UNIQUE KEY `unique_user_case` (`user_id`,`case_id`),
  KEY `case_id` (`case_id`),
  FOREIGN KEY (`user_id`) REFERENCES `users` (`user_id`) ON DELETE CASCADE,
  FOREIGN KEY (`case_id`) REFERENCES `cases` (`case_id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci AUTO_INCREMENT=330016;

DROP TABLE IF EXISTS `user_streaks`;
CREATE TABLE `user_streaks` (
  `user_id` int NOT NULL,
  `current_streak` int DEFAULT '0',
  `last_solved_date` date DEFAULT NULL,
  PRIMARY KEY (`user_id`) ,
  FOREIGN KEY (`user_id`) REFERENCES `users` (`user_id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

DROP TABLE IF EXISTS `users`;
CREATE TABLE `users` (
  `user_id` int NOT NULL AUTO_INCREMENT,
  `full_name` varchar(100) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `email` varchar(150) COLLATE utf8mb4_general_ci DEFAULT NULL,
