INSERT INTO `case_objectives` (`objective_id`, `case_id`, `objective_order`, `objective_text`, `expected_query`, `validation_type`, `required_keyword`, `points`) VALUES 
(1, 19, 1, 'List all students in the system.', 'SELECT name FROM persons WHERE role = \'Student\';', 'result', NULL, 10),
(2, 19, 2, 'Find students aged between 15 and 18.', 'SELECT name FROM persons WHERE role = \'Student\' AND age BETWEEN 15 AND 18;', 'result', NULL, 15),
(3, 19, 3, 'Find students aged between 15 and 18 who have a criminal record. Order them alphabetically.', 'SELECT name FROM persons WHERE role = \'Student\' AND age BETWEEN 15 AND 18 AND criminal_record = 1 ORDER BY name;', 'result', NULL, 20),
(4, 20, 1, 'List all students whose name starts with letter A.', 'SELECT name FROM persons WHERE role = \'Student\' AND name LIKE \'A%\';', 'result', NULL, 10),
(5, 20, 2, 'Find students whose age is either 15, 16, or 17.', 'SELECT name FROM persons WHERE role = \'Student\' AND age IN (15,16,17);', 'result', NULL, 15),
(6, 20, 3, 'Find students aged between 14 and 18 who have no criminal record. Order them by age ascending.', 'SELECT name FROM persons WHERE role = \'Student\' AND age BETWEEN 14 AND 18 AND criminal_record = 0 ORDER BY age ASC;', 'result', NULL, 20),
(7, 21, 1, 'List all staff members.', 'SELECT name FROM persons WHERE role = \'Staff\';', 'result', NULL, 10),
(8, 21, 2, 'Find all individuals with a criminal record.', 'SELECT name FROM persons WHERE criminal_record = 1;', 'result', NULL, 15),
(9, 21, 3, 'Find staff members aged between 25 and 60 who have a criminal record. Order by name.', 'SELECT name FROM persons WHERE role = \'Staff\' AND age BETWEEN 25 AND 60 AND criminal_record = 1 ORDER BY name;', 'result', NULL, 20),
(10, 22, 1, 'List all staff members from persons table Where the role is Staff', NULL, 'pattern', 'WHERE role', 20),
(11, 22, 2, 'Find staff members with a criminal record who are older than 30.', NULL, 'pattern', 'AND criminal_record', 25),
(12, 22, 3, 'List staff members with criminal record sorted from oldest to youngest.', NULL, 'pattern', 'ORDER BY', 25),
(13, 23, 1, 'Find all persons who were in the Library on 2026-04-09.', NULL, 'pattern', 'place_id', 20),
(14, 23, 2, 'Filter individuals who were in the Library at 14:00.', NULL, 'pattern', 'visit_time', 25),
(15, 23, 3, 'Identify which of them has a criminal record.', NULL, 'pattern', 'criminal_record', 25),
(16, 24, 1, 'Find persons who were in the Cafeteria on 2026-03-19.', NULL, 'pattern', 'place_id', 20),
(17, 24, 2, 'Filter persons present at 12:30.', NULL, 'pattern', 'visit_time', 25),
(18, 24, 3, 'Identify who among them has a criminal record.', NULL, 'pattern', 'criminal_record', 25),
(19, 25, 1, 'Find persons who were in the Laboratory on 2026-04-10.', NULL, 'pattern', 'place_id', 20),
(20, 25, 2, 'Filter persons around 10:00.', NULL, 'pattern', 'visit_time', 25),
(21, 25, 3, 'Check who has a criminal record.', NULL, 'pattern', 'criminal_record', 25),
(22, 26, 1, 'Find persons who were in the Clinic on 2026-04-10.', NULL, 'pattern', 'place_id', 20),
(23, 26, 2, 'Filter persons present at 11:00.', NULL, 'pattern', 'visit_time', 25),
(24, 26, 3, 'Identify who has a criminal record.', NULL, 'pattern', 'criminal_record', 25),
(60025, 30029, 1, 'Retrieve the names and roles of all persons from the persons table.', 'SELECT name, role FROM persons;', 'result', NULL, 15),
(60026, 30029, 2, 'Retrieve all records from the persons table ordered by person_id ascending.', 'SELECT * FROM persons ORDER BY person_id ASC;', 'result', NULL, 15),
(60027, 30029, 3, 'Identify staff and janitors who have prior criminal records (role IN (\"Janitor\", \"Staff\") AND criminal_record = 1). Note George Ramos and Oscar Villanueva as persons of interest.', 'SELECT person_id, name, role, age FROM persons WHERE role IN (\'Janitor\', \'Staff\') AND criminal_record = 1 ORDER BY person_id;', 'result', NULL, 20),
(60028, 30030, 1, 'Count how many persons have prior criminal records (criminal_record = 1).', 'SELECT COUNT(*) AS total_flagged FROM persons WHERE criminal_record = 1;', 'result', NULL, 15),
(60029, 30030, 2, 'Retrieve all columns of persons with prior criminal records ordered by person_id.', 'SELECT * FROM persons WHERE criminal_record = 1 ORDER BY person_id ASC;', 'result', NULL, 15),
(60030, 30030, 3, 'Pinpoint the only flagged Janitor on campus who holds master keys to the warehouse (role = \"Janitor\" AND criminal_record = 1). Pinpoints George Ramos!', 'SELECT person_id, name, role, age FROM persons WHERE role = \'Janitor\' AND criminal_record = 1;', 'result', NULL, 20),
(60031, 30031, 1, 'Retrieve the name, role, and age of all students under age 25.', 'SELECT name, role, age FROM persons WHERE role = \'Student\' AND age < 25;', 'result', NULL, 15),
(60032, 30031, 2, 'List all persons under age 25 ordered by age ascending.', 'SELECT * FROM persons WHERE age < 25 ORDER BY age ASC;', 'result', NULL, 15),
(60033, 30031, 3, 'Pinpoint young students with a prior criminal record linked to campus thefts (role = \"Student\", age < 25, criminal_record = 1) ordered by name. Reveals Ethan Cruz and Lara Flores!', 'SELECT person_id, name, role, age FROM persons WHERE role = \'Student\' AND age < 25 AND criminal_record = 1 ORDER BY name;', 'result', NULL, 20),
(60034, 30032, 1, 'Retrieve all details of persons whose role is \"Guard\".', 'SELECT * FROM persons WHERE role = \'Guard\';', 'result', NULL, 15),
(60035, 30032, 2, 'SELECT only the name and age columns of all guards ordered alphabetically by name.', 'SELECT name, age FROM persons WHERE role = \'Guard\' ORDER BY name ASC;', 'result', NULL, 15),
(60036, 30032, 3, 'Pinpoint the security guard who has a prior criminal record (role = \"Guard\" AND criminal_record = 1). This exposes Carlos Mendoza!', 'SELECT person_id, name, role, age FROM persons WHERE role = \'Guard\' AND criminal_record = 1;', 'result', NULL, 20),
(60037, 30033, 1, 'Retrieve evidence_id, evidence_type, and severity for all evidence items with severity >= 4.', 'SELECT evidence_id, evidence_type, severity FROM evidence WHERE severity >= 4;', 'result', NULL, 15),
(60038, 30033, 2, 'Retrieve all columns from the evidence table for severity >= 4 ordered by severity DESC, evidence_id ASC.', 'SELECT * FROM evidence WHERE severity >= 4 ORDER BY severity DESC, evidence_id ASC;', 'result', NULL, 15),
(60039, 30033, 3, 'Pinpoint the critical severity 5 evidence located at the Warehouse (place_id = 5) and reveal which suspect person_id it incriminates (George Ramos, person_id = 7)!', 'SELECT evidence_id, evidence_type, severity, person_id FROM evidence WHERE severity = 5 AND place_id = 5;', 'result', NULL, 20),
(60040, 30034, 1, 'Join evidence with places and list evidence_type alongside place_name.', 'SELECT e.evidence_type, pl.place_name FROM evidence e JOIN places pl ON e.place_id = pl.place_id;', 'result', NULL, 15),
(60041, 30034, 2, 'Count evidence items per place ordered by evidence_count DESC, place_name ASC.', 'SELECT pl.place_name, COUNT(e.evidence_id) AS evidence_count FROM places pl JOIN evidence e ON pl.place_id = e.place_id GROUP BY pl.place_id, pl.place_name ORDER BY evidence_count DESC, pl.place_name ASC;', 'result', NULL, 15),
(60042, 30034, 3, 'Pinpoint the single location with the highest evidence count having at least 3 evidence items. Confirms Warehouse is the primary crime scene!', 'SELECT pl.place_name, COUNT(e.evidence_id) AS evidence_count FROM places pl JOIN evidence e ON pl.place_id = e.place_id GROUP BY pl.place_id, pl.place_name HAVING COUNT(e.evidence_id) >= 3 ORDER BY evidence_count DESC;', 'result', NULL, 20),
(60043, 30035, 1, 'Retrieve all visit logs for the Warehouse (place_id = 5).', 'SELECT * FROM person_locations WHERE place_id = 5;', 'result', NULL, 15),
(60044, 30035, 2, 'Join persons with person_locations and retrieve p.name, p.role, and pl.visit_time at the Warehouse ordered by visit_time ASC.', 'SELECT p.name, p.role, pl.visit_time FROM persons p JOIN person_locations pl ON p.person_id = pl.person_id WHERE pl.place_id = 5 ORDER BY pl.visit_time ASC;', 'result', NULL, 15),
(60045, 30035, 3, 'Pinpoint the earliest visitor who entered the Warehouse before 10:00 AM. Pinpoints George Ramos (entered at 09:50:00) as the prime suspect inside during the break-in!', 'SELECT p.person_id, p.name, p.role, pl.visit_time FROM persons p JOIN person_locations pl ON p.person_id = pl.person_id WHERE pl.place_id = 5 AND pl.visit_time < \'2026-04-10 10:00:00\';', 'result', NULL, 20),
(60046, 30036, 1, 'Retrieve all reported crimes from the crime_events table.', 'SELECT crime_id, crime_name, crime_time FROM crime_events;', 'result', NULL, 15),
(60047, 30036, 2, 'Join crime_events with places and select ce.crime_name, pl.place_name, pl.location_type, ce.crime_time ordered by crime_id.', 'SELECT ce.crime_name, pl.place_name, pl.location_type, ce.crime_time FROM crime_events ce JOIN places pl ON ce.place_id = pl.place_id ORDER BY ce.crime_id;', 'result', NULL, 15),
(60048, 30036, 3, 'Pinpoint the exact crime event and location of the Warehouse Break-in. Confirms crime occurred at place_id 5 (Warehouse) at 10:30 AM!', 'SELECT ce.crime_name, pl.place_name, ce.crime_time FROM crime_events ce JOIN places pl ON ce.place_id = pl.place_id WHERE ce.crime_name = \'Warehouse Break-in\';', 'result', NULL, 20),
(60049, 30037, 1, 'List all evidence items associated with a person_id.', 'SELECT evidence_id, evidence_type, person_id FROM evidence WHERE person_id IS NOT NULL;', 'result', NULL, 15),
(60050, 30037, 2, 'Count total evidence for persons with criminal records ordered by total_evidence DESC, name ASC.', 'SELECT p.name, p.role, COUNT(e.evidence_id) AS total_evidence FROM persons p JOIN evidence e ON p.person_id = e.person_id WHERE p.criminal_record = 1 GROUP BY p.person_id, p.name, p.role ORDER BY total_evidence DESC, p.name ASC;', 'result', NULL, 15),
(60051, 30037, 3, 'Pinpoint the suspect with criminal record whose evidence is located directly inside the Warehouse (place_id = 5). Conclusively reveals George Ramos!', 'SELECT p.person_id, p.name, p.role, COUNT(e.evidence_id) AS warehouse_evidence FROM persons p JOIN evidence e ON p.person_id = e.person_id WHERE p.criminal_record = 1 AND e.place_id = 5 GROUP BY p.person_id, p.name, p.role;', 'result', NULL, 20),
(60052, 30038, 1, 'Retrieve the names and ages of all persons with clean records (criminal_record = 0).', 'SELECT name, role, age FROM persons WHERE criminal_record = 0;', 'result', NULL, 15),
(60053, 30038, 2, 'List staff and personnel older than 30 with clean records ordered by age ASC.', 'SELECT name, role, age FROM persons WHERE criminal_record = 0 AND age > 30 ORDER BY age ASC;', 'result', NULL, 15),
(60054, 30038, 3, 'Pinpoint the trustworthy clean-record Security Guard on duty who acts as key witness (role = \"Guard\" AND criminal_record = 0). Identifies Mark Dela Cruz!', 'SELECT person_id, name, role, age FROM persons WHERE role = \'Guard\' AND criminal_record = 0;', 'result', NULL, 20),
(60055, 30039, 1, 'Retrieve the exact timestamp when the Warehouse Break-in occurred.', 'SELECT crime_name, crime_time FROM crime_events WHERE crime_name = \'Warehouse Break-in\';', 'result', NULL, 15),
(60056, 30039, 2, 'Retrieve persons who visited the Warehouse (place_id = 5) before the Warehouse Break-in crime time ordered by visit_time.', 'SELECT p.name, p.role, pl.visit_time FROM persons p JOIN person_locations pl ON p.person_id = pl.person_id WHERE pl.place_id = 5 AND pl.visit_time < (SELECT crime_time FROM crime_events WHERE crime_name = \'Warehouse Break-in\') ORDER BY pl.visit_time ASC;', 'result', NULL, 15),
(60057, 30039, 3, 'Pinpoint which Warehouse visitor before the crime has a criminal record. Direct proof: George Ramos was present before the break-in with a prior record!', 'SELECT p.person_id, p.name, p.role, pl.visit_time FROM persons p JOIN person_locations pl ON p.person_id = pl.person_id WHERE pl.place_id = 5 AND p.criminal_record = 1 AND pl.visit_time < (SELECT crime_time FROM crime_events WHERE crime_name = \'Warehouse Break-in\');', 'result', NULL, 20),
(60058, 30040, 1, 'Find the maximum severity score across all collected evidence.', 'SELECT MAX(severity) AS max_severity FROM evidence;', 'result', NULL, 15),
(60059, 30040, 2, 'Retrieve all evidence matching the maximum severity along with suspect name and place name ordered by evidence_id.', 'SELECT e.evidence_type, e.severity, p.name AS suspect_name, pl.place_name FROM evidence e JOIN persons p ON e.person_id = p.person_id JOIN places pl ON e.place_id = pl.place_id WHERE e.severity = (SELECT MAX(severity) FROM evidence) ORDER BY e.evidence_id ASC;', 'result', NULL, 15),
(60060, 30040, 3, 'Pinpoint the maximum severity (5) evidence specifically found at the Warehouse crime scene. Directly exposes George Ramos and the Security Footage!', 'SELECT e.evidence_type, e.severity, p.name AS suspect_name FROM evidence e JOIN persons p ON e.person_id = p.person_id WHERE e.severity = (SELECT MAX(severity) FROM evidence) AND e.place_id = 5;', 'result', NULL, 20),
(60061, 30041, 1, 'List all campus locations designated as Restricted zones.', 'SELECT place_id, place_name, location_type FROM places WHERE location_type = \'Restricted\';', 'result', NULL, 15),
(60062, 30041, 2, 'Find distinct persons who entered Restricted zones ordered by name.', 'SELECT DISTINCT p.name, p.role, pl.place_name FROM persons p JOIN person_locations loc ON p.person_id = loc.person_id JOIN places pl ON loc.place_id = pl.place_id WHERE pl.location_type = \'Restricted\' ORDER BY p.name ASC;', 'result', NULL, 15),
(60063, 30041, 3, 'Pinpoint the non-security employee with a criminal record who entered the Restricted Warehouse. Pinpoints George Ramos (Janitor) trespassing in restricted storage!', 'SELECT DISTINCT p.person_id, p.name, p.role, pl.place_name FROM persons p JOIN person_locations loc ON p.person_id = loc.person_id JOIN places pl ON loc.place_id = pl.place_id WHERE pl.location_type = \'Restricted\' AND p.role != \'Guard\' AND p.criminal_record = 1 AND pl.place_name = \'Warehouse\';', 'result', NULL, 20),
(60064, 30042, 1, 'Group evidence by person_id and count evidence items per person.', 'SELECT person_id, COUNT(evidence_id) AS evidence_count FROM evidence GROUP BY person_id;', 'result', NULL, 15),
(60065, 30042, 2, 'Find persons with criminal records who have more than 1 evidence item linked to them ordered by evidence_count DESC, name ASC.', 'SELECT p.name, p.role, COUNT(e.evidence_id) AS evidence_count FROM persons p JOIN evidence e ON p.person_id = e.person_id WHERE p.criminal_record = 1 GROUP BY p.person_id, p.name, p.role HAVING COUNT(e.evidence_id) > 1 ORDER BY evidence_count DESC, p.name ASC;', 'result', NULL, 15),
(60066, 30042, 3, 'Pinpoint the multi-evidence suspect whose multiple evidence items were both found at the Warehouse (place_id = 5). Undeniable proof: George Ramos has 2 items at the crime scene!', 'SELECT p.person_id, p.name, p.role, COUNT(e.evidence_id) AS warehouse_items FROM persons p JOIN evidence e ON p.person_id = e.person_id WHERE e.place_id = 5 AND p.criminal_record = 1 GROUP BY p.person_id, p.name, p.role HAVING COUNT(e.evidence_id) > 1;', 'result', NULL, 20),
(60067, 30043, 1, 'List all crime events with their place_id and crime_time.', 'SELECT crime_name, place_id, crime_time FROM crime_events;', 'result', NULL, 15),
(60068, 30043, 2, 'Identify all persons present at crime scenes within 1 hour before the crime occurred ordered by crime_name ASC, visit_time ASC.', 'SELECT p.name, p.role, ce.crime_name, pl.visit_time, ce.crime_time FROM persons p JOIN person_locations pl ON p.person_id = pl.person_id JOIN crime_events ce ON pl.place_id = ce.place_id WHERE pl.visit_time >= DATE_SUB(ce.crime_time, INTERVAL 1 HOUR) AND pl.visit_time <= ce.crime_time ORDER BY ce.crime_name ASC, pl.visit_time ASC;', 'result', NULL, 15),
(60069, 30043, 3, 'FINAL VERDICT: Pinpoint the individual with a prior criminal record caught inside the Warehouse within 1 hour of the break-in. CONGRATULATIONS: You have proven GEORGE RAMOS is the perpetrator!', 'SELECT p.person_id, p.name, p.role, ce.crime_name, pl.visit_time FROM persons p JOIN person_locations pl ON p.person_id = pl.person_id JOIN crime_events ce ON pl.place_id = ce.place_id WHERE p.criminal_record = 1 AND ce.crime_name = \'Warehouse Break-in\' AND pl.visit_time >= DATE_SUB(ce.crime_time, INTERVAL 1 HOUR) AND pl.visit_time <= ce.crime_time;', 'result', NULL, 20);
