INSERT INTO `case_study_materials` (`case_id`, `file_name`, `mime_type`, `file_size`, `file_data`, `uploaded_by`, `created_at`, `updated_at`) VALUES 
(30029, 'Cedula_Cabahel_John Carlo.pdf', 'application/pdf', 1548, , 20, '2026-09-11 03:36:55', '2026-09-11 03:36:55');
INSERT INTO `cases` (`case_id`, `title`, `description`, `objectives`, `dataset_id`, `difficulty_id`, `correct_query`, `base_points`, `is_active`, `unlock_xp_required`, `correct_suspect_id`, `mode`, `sql_type`, `setup_sql`, `expected_result_sql`) VALUES 
(17, 'Criminal Record Scan', 'A routine system scan flagged individuals with criminal history. Your task is to identify them from the database.', '1. Examine the persons table.\r\n2. Filter individuals with criminal_record = 1.\r\n3. Display their names only.', 2, 1, 'SELECT name FROM persons WHERE criminal_record = 1;', 100, 0, 0, 7, 'Practice', 'DQL', NULL, NULL),
(18, 'The Stolen Laptop Investigation', 'A school laptop has been stolen. Security reports indicate that only individuals with prior criminal records are prime suspects. Evidence was collected at the scene. Identify the suspect most strongly connected to the crime.', '1. Identify individuals with criminal records.\r\n2. Join persons and evidence tables.\r\n3. Count evidence linked to each suspect.\r\n4. Determine who has the most evidence.\r\n5. Submit the suspect name as final answer.', 3, 2, 'SELECT p.name, COUNT(e.evidence_id) AS total_evidence FROM persons p JOIN evidence e ON p.person_id = e.person_id WHERE p.criminal_record = 1 GROUP BY p.name ORDER BY total_evidence DESC;', 200, 1, 0, 2, 'Rank', 'DQL', NULL, NULL),
(19, 'Cafeteria Conflict', 'A minor cafeteria conflict occurred. Filter individuals based on school roles and age.', 'Complete all objectives to identify key individuals involved.', 3, 1, NULL, 100, 0, 0, 5, 'Practice', 'DQL', NULL, NULL),
(20, 'Library Noise Complaint', 'The school librarian reported several disturbances. Filter students based on age and behavior.', 'Complete all objectives to identify potential troublemakers.', 3, 1, NULL, 100, 0, 0, 1, 'Practice', 'DQL', NULL, NULL),
(21, 'Missing Classroom Equipment', 'Equipment disappeared from a classroom. Filter individuals based on role and background.', 'Complete all objectives to narrow down possible suspects.', 3, 1, NULL, 120, 0, 0, 15, 'Practice', 'DQL', NULL, NULL),
(22, 'The Missing Exam Papers', 'Printed exam papers disappeared from the faculty office. Only staff members had access. Investigate and identify the most suspicious staff member.', 'Complete all objectives and submit the name of the suspect.', 3, 1, NULL, 100, 0, 0, 15, 'Rank', 'DQL', NULL, NULL),
(23, 'Library Laptop Theft', 'A school laptop was stolen from the Library on 2026-03-18 at 14:00. Identify the suspect.', '1. Find persons in Library at 14:00\n2. Check criminal record\n3. Submit suspect name', 3, 1, NULL, 100, 0, 0, 3, 'Rank', 'DQL', NULL, NULL),
(24, 'Cafeteria Vandalism', 'The school cafeteria was vandalized on 2026-03-19 at 12:30. Identify the suspect.', '1. Find persons in Cafeteria at 12:30\r\n2. Check criminal record\r\n3. Submit suspect name', 3, 1, NULL, 100, 0, 0, 5, 'Rank', 'DQL', NULL, NULL),
(25, 'Science Lab Equipment Theft', 'A microscope was stolen from the Science Lab on 2026-03-20 at 10:00. Identify the suspect.', '1. Find persons in Science Lab at 10:00\r\n2. Check criminal record\r\n3. Submit suspect name', 3, 1, NULL, 100, 0, 0, 7, 'Rank', 'DQL', NULL, NULL),
(26, 'Suspicious Activity in the Clinic', 'On 2026-04-10 at 11:00, unusual movement was detected inside the School Clinic. Investigate who was present and identify the suspect.', '1. Find persons in Clinic at 11:00. 2. Filter by criminal record. 3. Identify the final suspect.', 3, 1, NULL, 100, 0, 0, 12, 'Rank', 'DQL', NULL, NULL),
(27, 'Insert a New Suspect', 'A new suspect has been identified. Insert a record for \'Carlos\', age 28, into the suspects table.', NULL, NULL, 1, 'INSERT INTO suspects (name, age) VALUES (\'Carlos\', 28)', 100, 0, 0, NULL, 'Practice', 'DML', 'DROP TABLE IF EXISTS suspects;\nCREATE TABLE suspects (id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(50), age INT);\nINSERT INTO suspects VALUES (1,\'Alice\',19),(2,\'Bob\',22)', 'SELECT * FROM suspects ORDER BY id'),
(28, 'Create an Evidence Table', 'The police database is missing an evidence tracking table. Create a table named \'evidence_log\' with columns: id (INT, primary key, auto_increment),  item_name (VARCHAR 100),  and severity (INT).', NULL, NULL, 1, 'CREATE TABLE evidence_log (id INT AUTO_INCREMENT PRIMARY KEY, item_name VARCHAR(100), severity INT)', 100, 0, 0, NULL, 'Practice', 'DDL', NULL, 'SHOW COLUMNS FROM evidence_log'),
(30029, 'The Full Roster', 'You have just been assigned to the Detective Query Unit. Your first task is to pull the complete list of all persons currently in the investigation database. Use a SELECT statement to retrieve every record from the persons table ordered by their ID.', '🎯 INVESTIGATION OBJECTIVES:\n1. Retrieve the names and roles of all persons from the persons table. (15 XP)\n2. Retrieve all records from the persons table ordered by person_id ascending. (15 XP)\n3. Identify staff and janitors who have prior criminal records (role IN (\"Janitor\", \"Staff\") AND criminal_record = 1). Note George Ramos and Oscar Villanueva as persons of interest. (20 XP)\n\n🔍 VERDICT INTEL: Complete all 3 objectives above to uncover the decisive evidence and pinpoint the prime suspect!', 1, 1, 'SELECT * FROM persons ORDER BY person_id', 100, 1, 0, 7, 'Practice', 'DQL', 'DROP TABLE IF EXISTS crime_events;\nDROP TABLE IF EXISTS person_locations;\nDROP TABLE IF EXISTS evidence;\nDROP TABLE IF EXISTS places;\nDROP TABLE IF EXISTS persons;\nCREATE TABLE persons (person_id INT PRIMARY KEY, name VARCHAR(100), role VARCHAR(50), age INT, criminal_record TINYINT(1));\nINSERT INTO persons VALUES (1,\'Alex Carter\',\'Student\',19,0),(2,\'Bianca Reyes\',\'Student\',21,0),(3,\'Carlos Mendoza\',\'Guard\',34,1),(4,\'Diana Lopez\',\'Teacher\',29,0),(5,\'Ethan Cruz\',\'Student\',22,1),(6,\'Fiona Garcia\',\'Nurse\',31,0),(7,\'George Ramos\',\'Janitor\',45,1),(8,\'Hannah Lee\',\'Student\',18,0),(9,\'Ivan Torres\',\'Technician\',28,0),(10,\'Julia Santos\',\'Teacher\',41,0),(11,\'Kevin Lim\',\'Student\',23,0),(12,\'Lara Flores\',\'Student\',20,1),(13,\'Mark Dela Cruz\',\'Guard\',38,0),(14,\'Nina Ortiz\',\'Student\',19,0),(15,\'Oscar Villanueva\',\'Staff\',33,1);\nCREATE TABLE places (place_id INT PRIMARY KEY, place_name VARCHAR(100), location_type VARCHAR(50));\nINSERT INTO places VALUES (1,\'Library\',\'Academic\'),(2,\'Cafeteria\',\'Public\'),(3,\'Laboratory\',\'Restricted\'),(4,\'Main Office\',\'Administrative\'),(5,\'Warehouse\',\'Restricted\'),(6,\'Clinic\',\'Medical\');\nCREATE TABLE evidence (evidence_id INT PRIMARY KEY, evidence_type VARCHAR(100), person_id INT, place_id INT, severity INT);\nINSERT INTO evidence VALUES (1,\'Fingerprint\',3,5,3),(2,\'Broken Lock\',5,3,4),(3,\'Security Footage\',7,5,5),(4,\'Suspicious Email\',12,1,2),(5,\'Access Card Log\',15,5,4),(6,\'Tool Found\',7,5,3),(7,\'Witness Report\',3,5,2),(8,\'USB Device\',5,3,5);\nCREATE TABLE person_locations (record_id INT PRIMARY KEY, person_id INT, place_id INT, visit_time DATETIME);\nINSERT INTO person_locations VALUES (1,3,5,\'2026-04-10 10:15:00\'),(2,5,3,\'2026-04-10 10:30:00\'),(3,7,5,\'2026-04-10 09:50:00\'),(4,12,1,\'2026-04-09 14:00:00\'),(5,2,2,\'2026-04-09 12:15:00\'),(6,11,3,\'2026-04-10 11:00:00\'),(7,1,1,\'2026-04-08 08:00:00\'),(8,15,5,\'2026-04-10 10:40:00\'),(9,9,3,\'2026-04-10 09:00:00\'),(10,4,4,\'2026-04-10 13:00:00\');\nCREATE TABLE crime_events (crime_id INT PRIMARY KEY, crime_name VARCHAR(100), place_id INT, crime_time DATETIME);\nINSERT INTO crime_events VALUES (1,\'Warehouse Break-in\',5,\'2026-04-10 10:30:00\'),(2,\'Lab Equipment Theft\',3,\'2026-04-10 10:45:00\'),(3,\'Library Data Leak\',1,\'2026-04-09 15:00:00\')', 'SELECT * FROM persons ORDER BY person_id'),
(30030, 'Criminal Record Scan', 'Security has flagged several individuals for background checks. You need to isolate only those persons who have a criminal record (criminal_record = 1). These are your primary persons of interest.', '🎯 INVESTIGATION OBJECTIVES:\n1. Count how many persons have prior criminal records (criminal_record = 1). (15 XP)\n2. Retrieve all columns of persons with prior criminal records ordered by person_id. (15 XP)\n3. Pinpoint the only flagged Janitor on campus who holds master keys to the warehouse (role = \"Janitor\" AND criminal_record = 1). Pinpoints George Ramos! (20 XP)\n\n🔍 VERDICT INTEL: Complete all 3 objectives above to uncover the decisive evidence and pinpoint the prime suspect!', 1, 1, 'SELECT * FROM persons WHERE criminal_record = 1 ORDER BY person_id', 100, 1, 0, 7, 'Practice', 'DQL', 'DROP TABLE IF EXISTS crime_events;\nDROP TABLE IF EXISTS person_locations;\nDROP TABLE IF EXISTS evidence;\nDROP TABLE IF EXISTS places;\nDROP TABLE IF EXISTS persons;\nCREATE TABLE persons (person_id INT PRIMARY KEY, name VARCHAR(100), role VARCHAR(50), age INT, criminal_record TINYINT(1));\nINSERT INTO persons VALUES (1,\'Alex Carter\',\'Student\',19,0),(2,\'Bianca Reyes\',\'Student\',21,0),(3,\'Carlos Mendoza\',\'Guard\',34,1),(4,\'Diana Lopez\',\'Teacher\',29,0),(5,\'Ethan Cruz\',\'Student\',22,1),(6,\'Fiona Garcia\',\'Nurse\',31,0),(7,\'George Ramos\',\'Janitor\',45,1),(8,\'Hannah Lee\',\'Student\',18,0),(9,\'Ivan Torres\',\'Technician\',28,0),(10,\'Julia Santos\',\'Teacher\',41,0),(11,\'Kevin Lim\',\'Student\',23,0),(12,\'Lara Flores\',\'Student\',20,1),(13,\'Mark Dela Cruz\',\'Guard\',38,0),(14,\'Nina Ortiz\',\'Student\',19,0),(15,\'Oscar Villanueva\',\'Staff\',33,1);\nCREATE TABLE places (place_id INT PRIMARY KEY, place_name VARCHAR(100), location_type VARCHAR(50));\nINSERT INTO places VALUES (1,\'Library\',\'Academic\'),(2,\'Cafeteria\',\'Public\'),(3,\'Laboratory\',\'Restricted\'),(4,\'Main Office\',\'Administrative\'),(5,\'Warehouse\',\